export type BloxksPaywallResult = 'purchased' | 'restored' | 'cancelled'
export type BloxksPaywallEvent =
  | { kind: 'paywall_impression' | 'paywall_close'; fallback: boolean }
  | { kind: 'package_selected' | 'purchase_started' | 'purchase_cancelled'; productId: string }
  | { kind: 'purchase_completed'; productId: string; result: ZzzPurchaseResult; price?: number; currency?: string }
  | { kind: 'purchase_failed'; productId: string; error: string }
  | { kind: 'restore_completed'; restored: boolean }
  // Document fourni que le moteur ne sait pas dessiner : paywall de base montré à la place
  // (remplace l'impression ; le client peut toujours payer).
  | { kind: 'paywall_fallback'; reason: string }

/** Styles de police prêts à étaler (FONTS de zzz/fonts.ts) : display = titres, text = le reste. */
