const message = (locale: string) => MESSAGES[String(locale).slice(0, 2).toLowerCase()] || MESSAGES.en
const fill = (text: string, values: Record<string, string>) => text.replace(/\{(app|product|date)\}/g, (_m, k: string) => values[k] || '')

/** Date du changement programmé dans la langue du paywall (« 12 mars 2027 »), '' si illisible. */
function dateLabel(iso: string | null | undefined, locale: string): string {
  const t = iso ? Date.parse(iso) : NaN
  if (!isFinite(t)) return ''
  try { return new Date(t).toLocaleDateString(locale, { day: 'numeric', month: 'long', year: 'numeric' }) } catch { return new Date(t).toISOString().slice(0, 10) }
}

/** Issue d'un achat ou d'une restauration qui a son propre écran (même logique qu'un paywall codé). */
type Stage =
  | { kind: 'welcome'; result: BloxksPaywallResult }
  | { kind: 'credited'; productId: string }
  | { kind: 'scheduled'; productId: string; date: string | null }
  | { kind: 'activating'; productId: string }
  | { kind: 'owned' }

/** Couleurs du bouton d'achat du paywall (pour garder sa charte sur les écrans de résultat). */
function findPurchaseButton(n: PaywallNode | undefined): PaywallNode | null {
  if (!n) return null
  if (n.type === 'purchase_button') return n
  for (const c of Array.isArray(n.children) ? n.children : []) {
    const hit = findPurchaseButton(c)
    if (hit) return hit
  }
  return null
}

/** Langues de l'appareil sans dépendance : réglages iOS, puis Android, puis Intl. */
function deviceLocales(): string[] {
  try {
    const s = NativeModules.SettingsManager && NativeModules.SettingsManager.settings
    const ios = s && (s.AppleLanguages || (s.AppleLocale ? [s.AppleLocale] : null))
    if (ios && ios.length) return ios
    const android = NativeModules.I18nManager && NativeModules.I18nManager.localeIdentifier
    if (android) return [String(android).replace('_', '-')]
  } catch {}
  try { return [Intl.DateTimeFormat().resolvedOptions().locale] } catch { return ['en'] }
}

export function enginePackage(p: ZzzPackage): EnginePackage {
  return {
    productId: p.product.identifier,
    title: p.product.title,
    price: p.product.price,
    priceString: p.product.priceString,
    currency: p.product.currencyCode,
    period: p.product.subscriptionPeriod,
    trial: trialIso(productTrialDuration(p)),
    consumable: p.packageType === 'CUSTOM' && !p.product.subscriptionPeriod,
  }
}

/** Ombre douce (iOS : ombre réelle ; Android : élévation). */
function shadowStyle(level: any) {
  const s = shadowLevel(level)
  return s ? { shadowColor: '#000000', shadowOpacity: s.opacity, shadowRadius: s.radius, shadowOffset: { width: 0, height: s.y }, elevation: s.elevation } : null
}

/** Android : sans includeFontPadding, le texte est centré dans sa ligne comme sur iOS et dans l'aperçu. */
const TEXT_BOX = { includeFontPadding: false, textAlignVertical: 'center' as const }

function boxStyle(n: PaywallNode, scheme: any) {
  const shadow = shadowStyle(n.shadow)
  return [
    paddingStyle(n.padding),
    n.background ? { backgroundColor: colorOf(n.background, scheme) } : null,
    // Une ombre iOS disparaît avec overflow: 'hidden' : on ne coupe que les blocs sans ombre.
    typeof n.radius === 'number' ? (shadow ? { borderRadius: n.radius } : { borderRadius: n.radius, overflow: 'hidden' as const }) : null,
    n.border ? { borderWidth: n.border.width, borderColor: colorOf(n.border.color, scheme) } : null,
    shadow,
  ]
}

function fontFor(fonts: PaywallFonts | null | undefined, size: number, weight: number) {
  if (!fonts) return null
  const role = size >= 22 && fonts.display ? fonts.display : fonts.text
  if (!role) return null
  return (weight >= 700 ? role.bold : weight >= 500 ? role.semibold : role.regular) || role.regular || null
}

/** Police, taille, graisse et couleur d'un texte (son placement vient de layoutStyle). */
function textStyle(n: PaywallNode, scheme: any, fallbackColor: string, fonts?: PaywallFonts | null) {
  const size = typeof n.size === 'number' ? n.size : 16
  const weight = typeof n.weight === 'number' ? n.weight : 400
  const scale = typeScale(size)
  return [
    TEXT_BOX,
    {
      fontSize: size,
      fontWeight: String(weight) as any,
      lineHeight: scale.lineHeight,
      letterSpacing: scale.letterSpacing,
      color: colorOf(n.color, scheme, fallbackColor),
    },
    // Police du projet : la graisse vient du fichier de police (fontWeight seul est inerte).
    fontFor(fonts, size, weight),
  ]
}

/** Pictogramme dans une boîte fixe, posé sur une pastille ronde quand background est donné. */
function glyph(name: string, size: number, color: string | undefined, background: string | undefined, place?: any, key?: string) {
  const g = glyphLayout(size, !!background)
  return (
    <View key={key} style={[place, g.box as any, background ? { backgroundColor: background } : null]}>
      <Text style={[TEXT_BOX, g.char as any, { color: color, fontWeight: '700' }]}>{ICON_GLYPHS[name] || ''}</Text>
    </View>
  )
}

/**
 * Le paywall s'ouvre dans un Modal : fenêtre native à part, hors du SafeAreaProvider de l'app.
 * Sans fournisseur à lui, SafeAreaView y mesure 0 → croix et titre sous la barre d'état.
 */
/**
 * Apparence du paywall = celle de l'APP, pas du téléphone : une app sans mode sombre (app.json sans
 * userInterfaceStyle 'automatic') garde un paywall clair, même téléphone en sombre (Android suit
 * sinon le système). Aperçu web : le thème choisi dans l'aperçu.
 */
/** Fond sombre ? (#RGB / #RRGGBB[AA]) : décide de la couleur de l'heure et des icônes de la barre d'état. */
function isDarkColor(c: string | undefined): boolean {
  const m = /^#([0-9a-f]{6}(?:[0-9a-f]{2})?|[0-9a-f]{3})(?![0-9a-f])/i.exec(c || '')
  if (!m) return false
  const h = m[1].length === 3 ? m[1].split('').map((x) => x + x).join('') : m[1]
  const [r, g, b] = [0, 2, 4].map((i) => parseInt(h.slice(i, i + 2), 16) / 255)
  return 0.2126 * r + 0.7152 * g + 0.0722 * b < 0.5
}

export function usePaywallScheme(): 'light' | 'dark' {
  const system = useColorScheme()
  const cfg: any = (Constants && Constants.expoConfig) || {}
  const own = Platform.OS === 'ios' ? cfg.ios && cfg.ios.userInterfaceStyle : Platform.OS === 'android' ? cfg.android && cfg.android.userInterfaceStyle : null
  const style = own || cfg.userInterfaceStyle || (Platform.OS === 'web' ? 'automatic' : 'light')
  // Changement clair/sombre EN DIRECT, paywall ouvert : sur iOS, l'écran sous un Modal plein écran
  // ne reçoit plus l'avis du système, et useColorScheme reste figé jusqu'à la fermeture. On relit
  // le thème (lecture native immédiate) au retour au premier plan (Centre de contrôle, Réglages)
  // et chaque seconde. Web : useColorScheme suit déjà le navigateur.
  const [live, setLive] = useState(system)
  useEffect(() => { setLive(system) }, [system])
  useEffect(() => {
    if (style !== 'automatic' || Platform.OS === 'web') return
    const read = () => { const c = Appearance.getColorScheme(); if (c === 'dark' || c === 'light') setLive(c) }
    const sub = AppState.addEventListener('change', (state) => { if (state === 'active') read() })
    const timer = setInterval(read, 1000)
    return () => { sub.remove(); clearInterval(timer) }
  }, [style])
  if (style === 'dark') return 'dark'
  if (style === 'automatic') return live === 'dark' ? 'dark' : 'light'
  return 'light'
}

export function BloxksPaywall(props: BloxksPaywallProps) {
  return <SafeAreaProvider style={{ flex: 1 }}><PaywallScreen {...props} /></SafeAreaProvider>
}

export function PaywallScreen(props: BloxksPaywallProps) {
  const scheme = usePaywallScheme()
  const icon = props.icon !== undefined ? props.icon : BRANDING.icon
  const fonts = props.fonts !== undefined ? props.fonts : BRANDING.fonts
  const [packages, setPackages] = useState<EnginePackage[] | null>(props.packages || null)
  const [storePackages, setStorePackages] = useState<ZzzPackage[]>([])
  const [selected, setSelected] = useState<string | null>(null)
  const [busy, setBusy] = useState<'purchase' | 'restore' | null>(null)
  const [notice, setNotice] = useState<string | null>(null)
  const [stage, setStage] = useState<Stage | null>(null)
  const [attempt, setAttempt] = useState(0)
  const emit = (e: BloxksPaywallEvent) => { try { if (props.onEvent) props.onEvent(e) } catch {} }

  useEffect(() => {
    if (props.packages) return
    let alive = true
    fetchOffering().then((o) => {
      if (!alive) return
      const list = o ? o.availablePackages : []
      setStorePackages(list)
      setPackages(list.map(enginePackage))
    }).catch(() => { if (alive) setPackages([]) })
    return () => { alive = false }
  }, [props.packages, attempt])

  // Paiement reçu mais accès pas encore lu : on écoute les droits (et on les relit) jusqu'à l'ouverture.
  const activatingId = stage && stage.kind === 'activating' ? stage.productId : null
  useEffect(() => {
    if (!activatingId) return
    const ctxOf = productContext(activatingId) as { access?: string | null } | null
    const access = ctxOf && ctxOf.access ? ctxOf.access : undefined
    const stop = onCustomerInfoChange((info) => { if (isEntitlementActive(info, access)) setStage({ kind: 'welcome', result: 'purchased' }) })
    const timers = [4000, 12000, 30000].map((ms) => setTimeout(() => { getCustomerInfo().catch(() => {}) }, ms))
    return () => { stop(); timers.forEach(clearTimeout) }
  }, [activatingId])

  // Paywall distant prêt à dessiner, sinon paywall de base conforme.
  const view = useMemo(() => {
    if (!packages) return null
    const locales = props.locales || deviceLocales()
    const offered = props.trialEligible === false ? packages.map((p) => Object.assign({}, p, { trial: null })) : packages
    // Pages légales de l'app (enregistrées par le routeur) : jamais un lien laissé vide ou périmé dans le document.
    const appLinks = BRANDING.links && BRANDING.links.terms && BRANDING.links.privacy ? BRANDING.links : null
    const doc = props.paywall && appLinks ? Object.assign({}, props.paywall, { links: appLinks }) : props.paywall
    const remote = prepare(doc, offered, locales)
    if (remote.ok) return Object.assign({ fallback: false, reason: '' }, remote)
    const links = appLinks || (props.paywall && props.paywall.links ? props.paywall.links : { terms: '', privacy: '' })
    const basic = prepare(basicPaywall(offered, links), offered, locales)
    return basic.ok ? Object.assign({ fallback: true, reason: remote.reason }, basic) : null
  }, [packages, props.paywall, props.locales, props.trialEligible])

  useEffect(() => {
    if (!view) return
    // Repli sur un document reçu (pas un paywall de base demandé) : mesuré à part, le filet de sécurité de Bloxks Pay le surveille.
    if (view.fallback && props.paywall) emit({ kind: 'paywall_fallback', reason: view.reason })
    else emit({ kind: 'paywall_impression', fallback: view.fallback })
  }, [view])

  // Chargement et « aucune offre » : mêmes couleurs que le système (mode sombre compris).
  const plainBg = scheme === 'dark' ? '#000000' : '#FFFFFF'
  const plainFg = scheme === 'dark' ? '#FFFFFF' : '#111113'
  if (!packages) return <View style={{ flex: 1, alignItems: 'center', justifyContent: 'center', backgroundColor: plainBg }}><ActivityIndicator color={plainFg} /></View>
  if (!view) {
    // Aucune offre vendue par le store (hors ligne, produits pas encore validés…) : on le dit, on laisse réessayer et fermer.
    const m = message((props.locales || deviceLocales())[0] || 'en')
    return (
      <View style={{ flex: 1, alignItems: 'center', justifyContent: 'center', gap: 16, padding: 24, backgroundColor: plainBg }}>
        <Text style={{ textAlign: 'center', fontSize: 15, color: plainFg }}>{m.unavailable}</Text>
        {props.packages ? null : <Pressable accessibilityRole="button" hitSlop={12} onPress={() => { setPackages(null); setAttempt(attempt + 1) }}><Text style={{ fontSize: 15, fontWeight: '600', color: plainFg }}>{m.retry}</Text></Pressable>}
        <Pressable accessibilityRole="button" hitSlop={12} onPress={() => props.onClose('cancelled')}><Text style={{ fontSize: 15, fontWeight: '600', color: plainFg }}>{m.close}</Text></Pressable>
      </View>
    )
  }

  const doc = view.paywall
  const locale = view.locale
  const ctx: EngineContext = { locale: locale, appName: props.appName || '', store: STORE, packages: view.packages }
  const current = selected || view.defaultProductId
  const pkgOf = (id: string | null) => view.packages.find((p) => p.productId === id) || null
  const fg = scheme === 'dark' ? '#FFFFFF' : '#111113'

  const close = (result: BloxksPaywallResult) => {
    emit({ kind: 'paywall_close', fallback: view.fallback })
    props.onClose(result)
  }

  const m = message(locale)
  const buy = async () => {
    const target = storePackages.find((p) => p.product.identifier === current)
    if (busy || !current) return
    setNotice(null)
    emit({ kind: 'purchase_started', productId: current })
    if (!target) { emit({ kind: 'purchase_failed', productId: current, error: 'not_loaded' }); setNotice(m.failed); return }
    setBusy('purchase')
    try {
      const r = await purchasePackage(target)
      // Feuille fermée ou double appui : rien à dire.
      if (r.cancelled) { emit({ kind: 'purchase_cancelled', productId: current }); return }
      if (r.error === 'purchase_in_progress') return
      const shown = pkgOf(current)
      const consumable = !!(shown && shown.consumable)
      // Changement d'offre programmé par Apple : rien n'est payé, ce n'est pas un achat.
      if (r.scheduledChange) { setStage({ kind: 'scheduled', productId: r.scheduledChange.productIdentifier, date: r.scheduledChange.date }); return }
      if (r.success) {
        emit({ kind: 'purchase_completed', productId: current, result: r, price: shown ? shown.price : undefined, currency: shown ? shown.currency : undefined })
        if (props.onPurchased) props.onPurchased(r)
        // Pack : crédité par l'app via onConsumableDelivered (une fois par transaction).
        else if (consumable) deliverConsumable(r)
        if (consumable) setStage({ kind: 'credited', productId: current })
        else setStage(r.entitlementActive ? { kind: 'welcome', result: 'purchased' } : { kind: 'activating', productId: current })
        return
      }
      if (r.error === 'already_owned_lifetime' || (r.entitlementActive && !consumable)) { setStage({ kind: 'owned' }); return }
      emit({ kind: 'purchase_failed', productId: current, error: r.error || 'unknown' })
      const e = r.error || ''
      setNotice(e === 'pending' ? m.pending : e === 'timeout' ? m.timeout : e === 'store_build_required' ? m.storeBuild : e === 'pending_verification' ? m.coinsSoon : m.failed)
    } catch {
      setNotice(m.failed)
    } finally {
      setBusy(null)
    }
  }

  const restore = async () => {
    if (busy) return
    setNotice(null)
    setBusy('restore')
    try {
      const r = await restorePurchases()
      emit({ kind: 'restore_completed', restored: !!r.entitlementActive })
      if (r.entitlementActive) setStage({ kind: 'welcome', result: 'restored' })
      else setNotice(r.error ? m.restoreFailed : m.nothing)
    } catch {
      setNotice(m.restoreFailed)
    } finally {
      setBusy(null)
    }
  }

  const act = (action: string) => {
    if (action === 'close') close('cancelled')
    else if (action === 'restore') void restore()
    else if (action === 'manage') manageSubscriptions().catch(() => {})
    else if ((action === 'terms' || action === 'privacy') && doc.links[action]) Linking.openURL(doc.links[action]).catch(() => {})
  }

  const rootBg = colorOf(doc.root.background, scheme, scheme === 'dark' ? '#000000' : '#FFFFFF')
  const textOf = (lid: string) => textFor(doc, locale, lid)
  const draw = (raw: PaywallNode, key: string, pkg: EnginePackage | null, parent: LayoutParent): any => {
    // Une carte d'offre est « choisie » d'après SON produit ; ses textes, d'après la carte qui les contient.
    const selectedHere = raw.type === 'package' ? raw.product === current : !!pkg && pkg.productId === current
    const target = pkg || pkgOf(current)
    const n = resolveNode(raw, { selected: selectedHere, introOffer: !!(target && target.trial) })
    const say = (lid: string) => interpolate(textFor(doc, locale, lid), target, ctx)
    const place: any = layoutStyle(n, parent)
    switch (n.type) {
      case 'stack': {
        const inner = childParent(n, parent)
        if (n.axis === 'z') {
          return (
            <View key={key} style={[place, ...boxStyle(n, scheme)]}>
              {n.children.map((c: PaywallNode, i: number) => (
                <View key={i} style={layerStyle(n, i) as any}>{draw(c, key + '.' + i, pkg, inner)}</View>
              ))}
            </View>
          )
        }
        return (
          <View key={key} style={[place, ...boxStyle(n, scheme)]}>
            {n.children.map((c: PaywallNode, i: number) => draw(c, key + '.' + i, pkg, inner))}
          </View>
        )
      }
      case 'text':
        return <Text key={key} style={[place, ...textStyle(n, scheme, fg, fonts)]}>{say(n.lid)}</Text>
      case 'image': {
        const uri = scheme === 'dark' && n.src.dark ? n.src.dark : n.src.light
        return <Image key={key} source={{ uri: uri }} resizeMode={n.fit === 'contain' ? 'contain' : 'cover'} style={[place, { borderRadius: n.radius || 0 }]} />
      }
      case 'icon':
        return glyph(n.name, n.size || 20, colorOf(n.color, scheme, fg), colorOf(n.background, scheme), place, key)
      case 'app_icon': {
        const size = n.size || 72
        const radius = typeof n.radius === 'number' ? n.radius : Math.round(size * 0.225)
        const frame = [place, { width: size, height: size, borderRadius: radius }, shadowStyle(n.shadow)]
        if (icon) return <View key={key} style={frame}><Image source={icon} accessibilityIgnoresInvertColors style={{ width: size, height: size, borderRadius: radius }} /></View>
        // Pas encore d'icône : tuile à l'initiale de l'app, aux couleurs du paywall.
        return (
          <View key={key} style={[...frame, { backgroundColor: colorOf(n.background, scheme, fg), alignItems: 'center', justifyContent: 'center' }]}>
            <Text style={[TEXT_BOX, { fontSize: Math.round(size * 0.46), lineHeight: Math.round(size * 0.56), fontWeight: '800', color: colorOf(n.color, scheme, rootBg) }, fontFor(fonts, 30, 800)]}>{appInitial(ctx.appName)}</Text>
          </View>
        )
      }
      case 'spacer':
        return <View key={key} style={place} />
      case 'feature_list': {
        const f = featureLayout(n, parent)
        return (
          <View key={key} style={place}>
            {n.items.map((lid: string, i: number) => (
              <View key={i} style={f.row as any}>
                {glyph(n.icon || 'check', f.glyphSize, colorOf(n.iconColor, scheme, colorOf(n.color, scheme, fg)), colorOf(n.iconBackground, scheme))}
                <Text style={[...textStyle(n, scheme, fg, fonts), f.text as any]}>{say(lid)}</Text>
              </View>
            ))}
          </View>
        )
      }
      case 'package': {
        const own = pkgOf(n.product)
        if (!own) return null
        const inner = childParent(n, parent)
        return (
          <Pressable
            key={key}
            accessibilityRole="radio"
            accessibilityState={{ selected: own.productId === current }}
            onPress={() => { setSelected(own.productId); emit({ kind: 'package_selected', productId: own.productId }) }}
            style={[place, ...boxStyle(n, scheme)]}
          >
            {n.children.map((c: PaywallNode, i: number) => draw(c, key + '.' + i, own, inner))}
          </Pressable>
        )
      }
      case 'purchase_button':
        return (
          <Pressable key={key} accessibilityRole="button" accessibilityState={{ disabled: !!busy, busy: busy === 'purchase' }} accessibilityLabel={busy === 'purchase' ? m.busy : undefined} disabled={!!busy} onPress={buy} style={[place, { opacity: busy ? 0.7 : 1 }, ...boxStyle(n, scheme)]}>
            {busy === 'purchase' ? <ActivityIndicator color={colorOf(n.color, scheme, fg)} /> : <Text style={[{ textAlign: place.alignItems === 'flex-start' ? 'left' : place.alignItems === 'flex-end' ? 'right' : 'center' }, ...textStyle(n, scheme, fg, fonts)]}>{say(n.lid)}</Text>}
          </Pressable>
        )
      case 'button': {
        // L'alignement du texte va au libellé ; la place dans le groupe, au bouton.
        const { textAlign, ...box } = place
        return (
          <Pressable key={key} style={box} accessibilityRole={n.action === 'terms' || n.action === 'privacy' ? 'link' : 'button'} accessibilityLabel={n.action === 'close' ? m.close : undefined} hitSlop={12} disabled={n.action === 'restore' && !!busy} onPress={() => act(n.action)}>
            {n.action === 'restore' && busy === 'restore' ? <ActivityIndicator /> : <Text style={[{ textAlign: textAlign }, ...textStyle(n, scheme, fg, fonts)]}>{say(n.lid)}</Text>}
          </Pressable>
        )
      }
      case 'disclosure':
        return <Text key={key} style={[place, ...textStyle(Object.assign({ size: 11 }, n), scheme, fg, fonts)]}>{disclosureText(pkgOf(current), ctx)}</Text>
    }
    return null
  }

  const footerBg = doc.footer ? colorOf(doc.footer.background, scheme, rootBg) : rootBg
  if (stage) {
    // Écran de résultat aux couleurs du paywall : icône, titre, phrase, un seul bouton.
    const cta = findPurchaseButton(doc.footer) || findPurchaseButton(doc.root)
    const ctaBg = (cta && colorOf(cta.background, scheme)) || '#2F6BFF'
    const ctaFg = (cta && colorOf(cta.color, scheme)) || '#FFFFFF'
    const nameOf = (id: string) => { const p = pkgOf(id) || packages.find((x) => x.productId === id) || null; return p ? interpolate('{{ product.name }}', p, ctx) : '' }
    const values = { app: ctx.appName, product: stage.kind === 'welcome' || stage.kind === 'owned' ? '' : nameOf(stage.productId), date: stage.kind === 'scheduled' ? dateLabel(stage.date, locale) : '' }
    const copy = stage.kind === 'welcome' ? [ctx.appName ? m.welcome : m.welcome.replace(/\s*\{app\}/, ''), m.welcomeBody, 'check']
      : stage.kind === 'credited' ? [m.credited, m.creditedBody, 'gift']
      : stage.kind === 'scheduled' ? [m.scheduled, values.date ? m.scheduledBody : m.scheduledNext, 'check']
      : stage.kind === 'activating' ? [m.activating, m.activatingBody, 'sparkles']
      : [m.owned, m.ownedBody, 'check']
    const result: BloxksPaywallResult = stage.kind === 'welcome' ? stage.result : stage.kind === 'owned' ? 'restored' : stage.kind === 'credited' ? 'purchased' : 'cancelled'
    return (
      <View style={{ flex: 1, backgroundColor: rootBg }}>
        <StatusBar barStyle={isDarkColor(rootBg) ? 'light-content' : 'dark-content'} />
        <SafeAreaView style={{ flex: 1, alignItems: 'center', justifyContent: 'center', padding: 28, gap: 14 }}>
          {glyph(copy[2], 30, ctaFg, ctaBg)}
          <Text accessibilityRole="header" style={[TEXT_BOX, { fontSize: 26, lineHeight: 32, fontWeight: '800', color: fg, textAlign: 'center' }, fontFor(fonts, 26, 800)]}>{fill(copy[0], values)}</Text>
          <Text accessibilityLiveRegion="polite" style={[TEXT_BOX, { fontSize: 16, lineHeight: 22, color: fg, opacity: 0.8, textAlign: 'center' }, fontFor(fonts, 16, 400)]}>{fill(copy[1], values)}</Text>
          {stage.kind === 'activating' ? <ActivityIndicator color={fg} /> : null}
          <Pressable accessibilityRole="button" onPress={() => close(result)} style={{ alignSelf: 'stretch', marginTop: 12, paddingVertical: 16, borderRadius: 999, alignItems: 'center', backgroundColor: ctaBg }}>
            <Text style={[TEXT_BOX, { fontSize: 17, fontWeight: '700', color: ctaFg }, fontFor(fonts, 17, 700)]}>{stage.kind === 'activating' ? m.close : m.continue}</Text>
          </Pressable>
        </SafeAreaView>
      </View>
    )
  }
  // Zones sûres : la croix ne passe jamais sous l'encoche, le bouton d'achat jamais sous la barre d'accueil.
  // Barre d'état lisible sur le fond du paywall (remise comme avant à la fermeture : pile de StatusBar).
  return (
    <View style={{ flex: 1, backgroundColor: rootBg }}>
      <StatusBar barStyle={isDarkColor(rootBg) ? 'light-content' : 'dark-content'} />
      <SafeAreaView edges={['top', 'left', 'right']} style={{ flex: 1 }}>
        <ScrollView contentContainerStyle={{ flexGrow: 1 }} showsVerticalScrollIndicator={false}>{draw(doc.root, 'root', null, screenParent('root', textOf))}</ScrollView>
        {notice ? <Text accessibilityLiveRegion="polite" style={{ color: fg, textAlign: 'center', paddingHorizontal: 20, paddingTop: 8, fontSize: 13 }}>{notice}</Text> : null}
      </SafeAreaView>
      <SafeAreaView edges={['bottom', 'left', 'right']} style={{ backgroundColor: footerBg }}>
        {doc.footer ? draw(doc.footer, 'footer', null, screenParent('footer', textOf)) : null}
      </SafeAreaView>
    </View>
  )
}

export type RemotePaywallProps = {
  /** Emplacement publié dans Bloxks Pay ('default' = usePaywall().open() sans argument). */
  placement?: string
  onClose: (result: BloxksPaywallResult) => void
  /** Le paywall codé de l'app : affiché quand rien n'est publié (ou hors ligne sans cache). */
  fallback: () => ReactNode
  appName?: string
  onPurchased?: (result: ZzzPurchaseResult) => void
  icon?: ImageSourcePropType | null
  fonts?: PaywallFonts | null
  /** Paywall déjà résolu par le routeur (usePaywallResolution) : aucune seconde résolution. */
  resolution?: RemotePaywallResolution | null
}

/** Événement du paywall → mesure Bloxks Pay, rattachée au paywall, à sa révision et à la variante A/B. */
export function remotePaywallEvent(e: BloxksPaywallEvent, r: Extract<RemotePaywallResolution, { kind: 'remote' }>, placement: string) {
  const base = {
    kind: e.kind,
    placement: placement,
    paywallId: r.paywallId,
    revision: r.revision,
    experimentId: r.experimentId,
    variantId: r.variantId,
    productId: 'productId' in e ? e.productId : undefined,
    price: e.kind === 'purchase_completed' ? e.price : undefined,
    currency: e.kind === 'purchase_completed' ? e.currency : undefined,
  }
  return e.kind === 'paywall_fallback' ? Object.assign(base, { reason: e.reason }) : base
}

/**
 * Paywall à montrer pour l'emplacement, résolu quand active passe à true (configuration mémorisée
 * d'abord, au plus 1,5 s de réseau sinon). null tant que ce n'est pas connu. Groupe témoin : mesure
 * « holdout », onHoldout() (fermeture), et null : aucune fenêtre ne s'ouvre, jamais d'écran vide.
 */
export function usePaywallResolution(active: boolean, placement: string, onHoldout: () => void): RemotePaywallResolution | null {
  const [resolved, setResolved] = useState<{ placement: string; value: RemotePaywallResolution } | null>(null)
  useEffect(() => {
    setResolved(null)
    if (!active) return
    let alive = true
    const done = (value: RemotePaywallResolution) => {
      if (!alive) return
      if (value.kind === 'holdout') {
        trackPaywallEvent({ kind: 'holdout', placement: placement, experimentId: value.experimentId, variantId: value.variantId })
        onHoldout()
        return
      }
      setResolved({ placement: placement, value: value })
    }
    resolvePaywall(placement).then(done, () => done({ kind: 'none' }))
    return () => { alive = false }
  }, [active, placement])
  return resolved && resolved.placement === placement ? resolved.value : null
}

/**
 * Paywall de l'emplacement : paywall distant publié, sinon le paywall codé (fallback).
 * Groupe témoin d'un test A/B : rien n'est montré, fermeture immédiate ('cancelled').
 */
export function RemotePaywall(props: RemotePaywallProps) {
  const placement = props.placement || 'default'
  const own = usePaywallResolution(props.resolution === undefined, placement, () => props.onClose('cancelled'))
  const resolved = props.resolution !== undefined ? props.resolution : own
  if (!resolved || resolved.kind === 'holdout') return null
  if (resolved.kind === 'none') return <>{props.fallback()}</>
  const remote = resolved
  const appName = props.appName || (Constants.expoConfig && Constants.expoConfig.name) || ''
  return (
    <BloxksPaywall
      paywall={remote.document}
      appName={appName}
      onClose={props.onClose}
      onPurchased={props.onPurchased}
      trialEligible={remote.trialEligible !== false}
      icon={props.icon}
      fonts={props.fonts}
      onEvent={(e) => trackPaywallEvent(remotePaywallEvent(e, remote, placement))}
    />
  )
}

export default BloxksPaywall
